   "sector": "mundo",
   "titulo": "El Ejército yemení se retira de Bab al Mandeb para reforzar Adén ante el avance de la ofensiva hutí",
   "resumen": "Los rebeldes hutíes amplían su control sobre el estrecho, una importante vía marítima que da acceso al Canal de Suez desde el Índico.",
   "fuente": "DW Español",
   "url": "https://www.dw.com/es/el-ejército-yemení-se-retira-de-bab-al-mandeb-para-reforzar-adén-ante-el-avance-de-la-ofensiva-hutí/a-79951870?maca=spa-rss-sp-all-1122-xml-mrss",
   "fecha": "2026-11-15T11:15:00Z",
   "tipo": "internacional",
