   "geografia": {
    "version": 1,
    "ambito": "pendiente",
    "zona": "pendiente",
    "motivo": "sin_evidencia_geografica"
   },
   "ambito": "pendiente",
   "procedencia": "directa",
   "sintesis": "Los rebeldes hutíes amplían su control sobre el estrecho, una importante vía marítima que da acceso al Canal de Suez desde el Índico. Las Fuerzas Armadas del Sur -principal fuerza leal al Gobierno yemení internacionalmente reconocido- describieron en un comunicado la medida como un \"redespliegue militar dictado por la evolución de la situación en el campo de batalla y por nuevas amenazas a la seguridad\".",
   "puntos": [
    "Los rebeldes hutíes amplían su control sobre el estrecho, una importante vía marítima que da acceso al Canal de Suez desde el Índico.",
    "Las Fuerzas Armadas del Sur -principal fuerza leal al Gobierno yemení internacionalmente reconocido- describieron en un comunicado la medida como un \"redespliegue militar dictado por la evolución de la situación en el campo de batalla y por nuevas amenazas a la seguridad\".",
    "\"Esta medida se adopta priorizando la seguridad de la capital, Adén, y de las gobernaciones vecinas, así como el fortalecimiento de las líneas de frente y la respuesta ante las amenazas existentes\", añade."
   ]
